constexpr const Inventory* inventory(GameVersion version) {
    const auto index = static_cast<std::size_t>(version);
    return index < kGames.size() ? &kGames[index].inventory : nullptr;
}

constexpr const Menu* menu(GameVersion version) {
    const auto index = static_cast<std::size_t>(version);
    return index < kGames.size() ? &kGames[index].menu : nullptr;
}

constexpr const Action* action(GameVersion version) {
    const auto index = static_cast<std::size_t>(version);
    return index < kGames.size() ? &kGames[index].action : nullptr;
}

// The build whose identity words all match; null when none or several do.
template <typename ReadWord>
constexpr const Game* select(std::size_t textSize, ReadWord readWord) {
    const Game* match = nullptr;
    for (const auto& game : kGames) {
        bool valid = true;
        for (const auto& s : game.identity) {
            if (s.offset < 0 || static_cast<std::size_t>(s.offset) + 4 > textSize ||
                readWord(s.offset) != s.word) {
                valid = false;
                break;
            }
        }
        if (!valid) continue;
        if (match) return nullptr;
        match = &game;
    }
    return match;
}

